use vstd::prelude::*;
use vstd::vec::*;

verus! {

spec fn vec_eq<T>(v1: Vec<T>, v2: Vec<T>) -> bool
    recommends
        v1.len() == v2.len(),
{
    forall|i: int| 0 <= i < v1.len() ==> v1[i] == v2[i]
}

fn solve(t: Vec<char>) -> (result: Vec<char>)
    ensures
        result@.len() == t@.len(),
        forall|i: int| 0 <= i < t@.len() ==> result[i] == t[i],
        vec_eq(result, t),
{
    let mut result = Vec::with_capacity(t.len());
    
    let mut i: usize = 0;
    while i < t.len()
        invariant
            0 <= i <= t@.len(),
            result@.len() == i,
            forall|j: int| 0 <= j < i ==> result[j] == t[j],
            result@.len() <= t@.len(),
        decreases t@.len() - i,
    {
        result.push(t[i]);
        i = i + 1;
    }
    
    result
}

}
